package com.lexiscan.config; import com.lexiscan.user.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.context.annotation.Configuration;
@Configuration class AdminSeeder { @Bean CommandLineRunner adminSeed(UserRepository users,PasswordEncoder encoder,AppProperties p){return a->{if(p.admin().email()!=null&&!p.admin().email().isBlank()&&p.admin().password()!=null&&p.admin().password().length()>=12&&users.findByEmailIgnoreCase(p.admin().email()).isEmpty()){var u=new User();u.setName("LexiScan Administrator");u.setEmail(p.admin().email().toLowerCase());u.setPasswordHash(encoder.encode(p.admin().password()));u.setRole(Role.ADMIN);users.save(u);}};} }
